def diagnose(recall_at_k, faithfulness):
    # split the blame: which half is failing?
    if recall_at_k < 0.7:
        return "fix RETRIEVAL: gold chunk often not fetched"
    if faithfulness < 0.8:
        return "fix GENERATION: has context but answers unfaithfully"
    return "both halves healthy"

print(diagnose(recall_at_k=0.55, faithfulness=0.9))
# a single accuracy score could not have told you this

def recall_at_k(retrieved_ids, gold_ids, k):
    top = retrieved_ids[:k]
    return 1.0 if any(g in top for g in gold_ids) else 0.0

def reciprocal_rank(retrieved_ids, gold_ids):
    for i, cid in enumerate(retrieved_ids, start=1):
        if cid in gold_ids:
            return 1.0 / i        # first hit at rank i
    return 0.0

ret = ["c9", "c3", "c1"]; gold = {"c1"}
print(recall_at_k(ret, gold, k=3), reciprocal_rank(ret, gold))  # 1.0 0.333

