def recall_at_k(retrieved, gold, k):
    return 1.0 if any(g in retrieved[:k] for g in gold) else 0.0

def reciprocal_rank(retrieved, gold):
    for i, cid in enumerate(retrieved, start=1):
        if cid in gold:
            return 1.0 / i
    return 0.0

def evaluate(eval_set, run_rag, judge, k, thresholds):
    recalls, rrs, faiths = [], [], []
    for ex in eval_set:
        retrieved, answer = run_rag(ex["question"])
        gold = ex["gold"]
        recalls.append(recall_at_k(retrieved, gold, k))
        rrs.append(reciprocal_rank(retrieved, gold))
        # build the context text the generator actually saw
        context = " ".join(ex["corpus"][cid] for cid in retrieved if cid in ex["corpus"])
        faiths.append(judge(answer, context))
    n = len(eval_set)
    scores = {
        "recall@k": sum(recalls) / n,
        "mrr": sum(rrs) / n,
        "faithfulness": sum(faiths) / n,
    }
    failures = {m: scores[m] for m in thresholds if scores[m] < thresholds[m]}
    if failures:
        raise SystemExit(f"eval regression: {failures}")
    return scores

