CORPUS = {"c1": "refund in 5 business days", "c2": "ships worldwide", "c9": "about us"}

eval_set = [
    {"question": "refund time?", "gold": {"c1"}, "corpus": CORPUS},
    {"question": "shipping?", "gold": {"c2"}, "corpus": CORPUS},
]

# a fake RAG that retrieves correctly and answers faithfully
def good_rag(q):
    return (["c1", "c9"], "refund") if "refund" in q else (["c2", "c9"], "ships")

# judge stub: faithful if answer word appears in context
def judge(answer, context):
    return 1.0 if answer in context else 0.0

scores = evaluate(eval_set, good_rag, judge, k=3,
                  thresholds={"recall@k": 0.9, "faithfulness": 0.9})
assert scores["recall@k"] == 1.0
assert scores["faithfulness"] == 1.0

# a RAG that retrieves the wrong chunk -> recall drops, gate fails
def bad_rag(q):
    return (["c9"], "refund")

try:
    evaluate(eval_set, bad_rag, judge, k=3,
             thresholds={"recall@k": 0.9, "faithfulness": 0.9})
    raise AssertionError("should have failed the gate")
except SystemExit:
    pass
print("all tests passed")

