def mean_recall_at_k(examples, k):
    hits = 0
    for ex in examples:
        top = ex["retrieved"][:k]
        if any(g in top for g in ex["gold"]):
            hits += 1
    return hits / len(examples) if examples else 0.0

def mrr(examples):
    total = 0.0
    for ex in examples:
        rr = 0.0
        for rank, cid in enumerate(ex["retrieved"], start=1):
            if cid in ex["gold"]:
                rr = 1.0 / rank      # first relevant chunk only
                break
        total += rr
    return total / len(examples) if examples else 0.0

if __name__ == "__main__":
    data = [
        {"retrieved": ["c1", "c2"], "gold": {"c1"}},
        {"retrieved": ["c3", "c1"], "gold": {"c1"}},
        {"retrieved": ["c3", "c4"], "gold": {"c1"}},
    ]
    print(round(mean_recall_at_k(data, 2), 3), round(mrr(data), 3))
